// Format Output + Self-Check 8항목 자동 검증
// 입력: Claude 응답
// 출력: 검증 결과 + 정제된 컨텐츠

const BLOCKED_KEYWORDS = ['음주운전','마약','폭행','사망','장례','19금','노출','이재명','윤석열','한동훈','조국','사기','절도','살인','성적','선정적','음란'];

const raw = $input.first().json;
const contentText = raw?.content?.[0]?.text || '';

let parsed = null;
let parseError = null;
try {
  parsed = JSON.parse(contentText);
} catch (e) {
  // JSON 추출 시도
  const m = contentText.match(/\{[\s\S]*\}/);
  if (m) {
    try { parsed = JSON.parse(m[0]); } catch (e2) { parseError = e2.message; }
  } else {
    parseError = e.message;
  }
}

if (!parsed) {
  return [{ json: {
    ok: false,
    reason: 'claude_response_parse_failed',
    parseError,
    raw_excerpt: contentText.substring(0, 500),
  } }];
}

// 셀프체크 — JAC-1696 §6 자동 항목
const sec = parsed.sections || {};
const body_text = [
  sec.intro,
  sec.cultural_context,
  sec.closing,
  ...(sec.learning_points || []).map(lp => `${lp.phrase} ${lp.explanation}`),
].filter(Boolean).join(' ');

const korean_chars = (body_text.match(/[\uAC00-\uD7AF]/g) || []).length;
const lyrics_placeholder_present = (sec.lyrics_quote || '').includes('[LYRICS_PLACEHOLDER]');
const disclosure_present = !!(sec.ai_disclosure && sec.ai_disclosure.includes('AI'));
const source_present = !!(sec.source && sec.source.startsWith('출처'));
const blocked_kw = BLOCKED_KEYWORDS.find(k => (body_text + ' ' + (parsed.title||'')).includes(k));
const learning_points_count = (sec.learning_points || []).length;

const checks = {
  '1_korean_chars_min_600': korean_chars >= 600,
  '2_lyrics_placeholder_present': lyrics_placeholder_present,
  '3_ai_disclosure_present': disclosure_present,
  '4_source_url_present': source_present,
  '5_no_blocked_keywords': !blocked_kw,
  '6_learning_points_3': learning_points_count === 3,
  '7_title_exists': !!(parsed.title && parsed.title.length > 0),
  '8_title_length_under_60': (parsed.title || '').length <= 60,
  '9_slug_exists': !!(parsed.slug && parsed.slug.length > 0),
  '10_meta_description_exists': !!(parsed.meta_description && parsed.meta_description.length > 0),
  '11_meta_description_under_160': (parsed.meta_description || '').length <= 160,
  '12_tags_exist_and_are_array': !!(parsed.tags && Array.isArray(parsed.tags) && parsed.tags.length > 0),
};
// >>> JAC-1895 hexagon-anchor-backlink BEGIN
// Hexagon mode is opt-in via `body.hexagon_id`. When absent, we auto-pass to
// preserve the legacy single-article daily routine. Sister domains in hexagon
// mode must include the anchor slug (the hexagon_id) somewhere in body+meta —
// flexible enough to match `/dramas/<id>` or `/content/reviews/<id>-ko.html`
// or any other URL the publish layer adopts. The k-drama anchor self-passes.
const hxTrigger = $('Webhook Trigger').first().json.body || {};
const hxId = hxTrigger.hexagon_id || null;
const hxCategory = "k-pop";
let hxBacklinkOk;
if (!hxId) {
  hxBacklinkOk = true; // legacy mode
} else {
  hxBacklinkOk = (body_text || '').includes(hxId);
}
checks['14_anchor_backlink_present'] = hxBacklinkOk;
// <<< JAC-1895 hexagon-anchor-backlink END
const pass = Object.values(checks).every(Boolean);

return [{
  json: {
    ok: pass,
    self_check: checks,
    self_check_summary: pass ? `${Object.keys(checks).length}/${Object.keys(checks).length} 통과` : `${Object.values(checks).filter(Boolean).length}/${Object.keys(checks).length} 통과 — 미통과: ${Object.entries(checks).filter(([k,v])=>!v).map(([k])=>k).join(', ')}`,
    blocked_keyword_hit: blocked_kw || null,
    korean_chars,
    draft: parsed,
    metadata: {
      keyword: $('Filter & Select Topic').first().json.keyword,
      source: $('Filter & Select Topic').first().json.selected,
      generated_at: new Date().toISOString(),
      model: $('Webhook Trigger').first().json.body.model || 'claude-sonnet-4-6',
    },
  },
}];
